solutions.naive:
class Solution:
    def maxDistance(self, position: list[int], m: int) -> int:
        position.sort()
        for dist in range(position[-1] - position[0], 0, -1):
            count = 1
            last = position[0]
            for p in position[1:]:
                if p - last >= dist:
                    count += 1
                    last = p
            if count >= m:
                return dist
        return 0

